function parseTimeoutMs(value) {
  if (typeof value === "number") {
    return Math.round(value * 1000);
  }
  const match = String(value).trim().match(/^(-?\d+(?:\.\d+)?)\s*(ms|s|m)?$/);
  if (match) {
    const amount = parseFloat(match[1]);
    const unit = match[2] || "s";
    if (unit === "ms") return Math.round(amount);
    if (unit === "m") return Math.round(amount * 60 * 1000);
    return Math.round(amount * 1000);
  }
  const fallback = parseFloat(String(value).trim());
  return Number.isNaN(fallback) ? 0 : Math.round(fallback * 1000);
}

function parseEndpoint(raw) {
  const str = String(raw).trim();
  const colonIdx = str.lastIndexOf(":");
  if (colonIdx !== -1) {
    const portPart = str.slice(colonIdx + 1);
    const hostPart = str.slice(0, colonIdx);
    if (/^\d+$/.test(portPart) && hostPart.lastIndexOf(":") === -1) {
      return { host: hostPart, port: parseInt(portPart, 10) };
    }
  }
  return { host: str, port: 443 };
}

function parseRetries(value) {
  if (value === undefined || value === null || value === "") {
    return 0;
  }
  const parsed = parseInt(value, 10);
  return Number.isNaN(parsed) ? 0 : parsed;
}

function parseTags(value) {
  const rawItems = [];
  if (Array.isArray(value)) {
    for (const item of value) {
      rawItems.push(String(item));
    }
  } else if (typeof value === "string") {
    for (const item of value.split(",")) {
      rawItems.push(item);
    }
  }
  const seen = Object.create(null);
  const tags = [];
  for (const item of rawItems) {
    const tag = item.trim().toLowerCase();
    if (tag === "" || seen[tag]) {
      continue;
    }
    seen[tag] = true;
    tags.push(tag);
  }
  tags.sort();
  return tags;
}

function parseEnabled(value) {
  if (value === true || value === 1) return true;
  if (value === false || value === 0) return false;
  const str = String(value).trim().toLowerCase();
  return str === "yes" || str === "true" || str === "on" || str === "1";
}

const v1Configs = tool("configs", {});

const notes = [];
for (const cfg of v1Configs) {
  notes.push(cfg && typeof cfg.owner_note === "string" ? cfg.owner_note : "");
}

const priorities = tool("judge_priorities", { notes: notes });

const v2Configs = [];
let index = 0;
for (const cfg of v1Configs) {
  const endpoint = parseEndpoint(cfg.endpoint);
  v2Configs.push({
    name: cfg.name,
    timeoutMs: parseTimeoutMs(cfg.timeout),
    host: endpoint.host,
    port: endpoint.port,
    retries: parseRetries(cfg.retries),
    tags: parseTags(cfg.tags),
    enabled: parseEnabled(cfg.enabled),
    priority: priorities[index] || "normal"
  });
  index++;
}

v2Configs;
